import { execFileSync } from "node:child_process";
const sha = process.argv[2];
const sleep = (ms) => Atomics.wait(new Int32Array(new SharedArrayBuffer(4)), 0, 0, ms);
const deadline = Date.now() + 25 * 60_000;
let limited = 0;
while (Date.now() < deadline) {
  let runs;
  try {
    runs = JSON.parse(execFileSync("gh", ["run", "list", "--repo", "mvhenten/stallion", "--workflow", "deploy.yml", "--limit", "5", "--json", "status,conclusion,headSha,databaseId"], { encoding: "utf8", stdio: ["ignore", "pipe", "pipe"] }));
  } catch (error) {
    if (/rate limit|403/i.test(String(error.stderr)) && limited++ < 5) { sleep(60_000); continue; }
    throw error;
  }
  const run = runs.find((r) => r.headSha === sha);
  if (run && run.status === "completed") { console.log(JSON.stringify(run)); process.exit(0); }
  sleep(30_000);
}
console.log("timed out");
process.exit(1);
EOF
